import {setArtwork} from './svg-render.js';
import {createState,NAMES,CHEM,active,point,pour,scoop,fitVial,fitBung,mixVial,clampSyringe,connect,connected,zeroSyringe,toggleClock,record,stepChemistry,saveTrial,nextTrial,meanRate,fairPair,physicsFor,detach,placeItem,stepPhysics} from './rates-model.js';
import {art,graph} from './rates-art.js';
import {initializeStorage} from './equipment-storage.js';
import {createEquipmentMenu} from './equipment-menu.js';
import {reviewQuestions,bindReviewQuestions} from './review-questions.js';
const $=id=>document.getElementById(id),bench=$('bench'),layer=$('apparatus'),NS='http://www.w3.org/2000/svg';
let state=initializeStorage(createState()),selected=null,drag=null,last=0,note='',menu,controlsMarkup='',dataMarkup='',flowUntil=0;
const groups=new Map();
for(const id of Object.keys(state.items)){const g=document.createElementNS(NS,'g');g.dataset.id=id;g.classList.add('object');g.setAttribute('role','button');g.setAttribute('tabindex','0');g.setAttribute('aria-label',NAMES[id]);g.addEventListener('focus',()=>{if(selected!==id)select(id);});layer.append(g);groups.set(id,g);}
$('equipment').innerHTML=Object.entries(NAMES).map(([id,n])=>`<button class="equipment-button" data-equipment="${id}" aria-pressed="false">${n}</button>`).join('');
function context(){const o=state.items[selected];if(!active(o))return{label:'Select apparatus',buttons:[],disabled:true,hint:'Drag apparatus from Equipment.'};
 if(o.kind==='spatula')return{label:o.chips+o.powder>0?'Deliver solid':'Take 0.10 g',buttons:[['fine','Take 0.01 g']],hint:'Place the scoop over chips/powder to load it, then above the flask to deliver. No timed stream.'};
 if(o.kind==='solidBottle')return{label:'Pour solid · 0.10 g',buttons:[],hint:`${(o.chips+o.powder).toFixed(2)} g remaining. All trial amounts are chosen by you.`};
 if(o.kind==='vial')return{label:o.parent?'Remove inner vial':'Fit inside flask',buttons:[['pour','Pour 10 mL']],hint:'The inner vial keeps acid separate until you deliberately tip it. Fill it before fitting the bung.'};
 if(o.kind==='bung')return{label:o.parent?'Remove bung':'Fit bung',buttons:[],hint:'A sealed flask and connected syringe collect gas. Removing the bung loses newly produced gas.'};
 if(o.kind==='gasSyringe')return{label:state.hose?'Disconnect tube':'Connect tube',buttons:[['clamp',state.links.length?'Release clamp':'Clamp to stand'],['seal',state.tight?'Loosen connector':'Tighten connector'],['zero','Empty syringe']],hint:'Clamp near the stand, fit the bung and connect. Read the piston face nearest the inlet. Emptying the syringe releases its gas; it does not reset the reaction.'};
 if(o.kind==='clampStand')return{label:'Move stand',buttons:[],disabled:true,hint:'Place the syringe near the upper clamp; select it and clamp it.'};
 if(o.id==='flask')return{label:!state.clock&&state.elapsed===0&&!state.records.length?'Tip vial & start clock':'Tip inner vial',buttons:[['mix-only','Tip without starting clock']],hint:'Start the clock before tipping. Acid touching carbonate starts the reaction, even if the clock is stopped or the gas line is open.'};
 return{label:'Pour 10 mL',buttons:[['fine','Pour 1 mL']],hint:'Position above the vial or flask. Each action adds one portion and stops. Water dilution and wrong amounts remain possible.'};
}
function renderData(){const signature=JSON.stringify([state.trialId,state.records,state.trials]);if(signature===dataMarkup)return;dataMarkup=signature;$('rates-graph').innerHTML=graph(state.trials,state);const all=state.trials.filter(t=>t.id!==state.trialId);if(state.records.length)all.push({id:state.trialId,records:state.records,charge:state.charge});$('measurements').innerHTML=all.flatMap(t=>t.records.map(r=>`<tr><td>${t.id}</td><td>${r.time.toFixed(1)}</td><td>${r.volume.toFixed(1)}</td></tr>`)).join('');$('trial-summary').innerHTML=all.map(t=>{const c=t.charge,m=c?c.chips+c.powder:0,r=meanRate(t.records);return `<p>Trial ${t.id}: ${c?`${c.chips>0&&c.powder>0?'mixed solids':c.powder>0?'powder':'chips'}, ${m.toFixed(3)} g; ${c.water.toFixed(1)} mL acid solution, ${(c.acid/c.water*1000).toFixed(3)} M`:'No reaction charge recorded'}. ${r?`Mean rate over ${r.a.time.toFixed(1)}–${r.b.time.toFixed(1)} s: ${r.value.toFixed(2)} mL s⁻¹.`:'Record two different times for a mean rate.'}</p>`;}).join('')+(state.trials.length>=2?`<p>${fairPair(state.trials.at(-2),state.trials.at(-1))?'The last two saved trials began with matched amounts and different pure solid forms. Check their full curves and any later leaks.':'The last two saved trials are not a matched chips–powder comparison. Check masses, acid volume/concentration, seals and clock timing.'}</p>`:'');}
function render(){for(const[id,g]of groups){const o=state.items[id];g.setAttribute('transform',`translate(${o.x} ${o.y}) rotate(${o.angle||0})`);setArtwork(g,art(o,state));g.classList.toggle('selected',id===selected);}if(selected)layer.append(groups.get(selected));for(const id of ['vial','bung'])if(state.items[id].parent)layer.append(groups.get(id));
 const b=state.items.bung,g=state.items.syringe,f=state.items.flask;$('streams').innerHTML=(state.hose?`<path d="M${b.x+20} ${b.y-12}C${b.x+80} ${b.y-80},${g.x-60} ${g.y-40},${g.x} ${g.y}" fill="none" stroke="${state.tight?'#5f9495':'#b58a55'}" stroke-width="6" pointer-events="none"/>`:'')+(performance.now()<flowUntil?state.flow.map(p=>`<path d="M${p.from.x} ${p.from.y}L${p.to.x} ${p.to.y}" stroke="#7eb9ca" stroke-width="4"/>`).join(''):'')+(state.rate>0?Array.from({length:5},(_,i)=>`<circle class="rates-bubble" cx="${f.x+(i*17%44)-22}" cy="${f.y+100-((state.time*30+i*11)%55)}" r="${2+i%3}"/>`).join(''):'');
 $('spills').innerHTML=state.spills.map(p=>`<ellipse cx="${p.x}" cy="523" rx="${Math.min(60,8+p.water)}" ry="5" fill="#89bdc6"/>`).join('');
 const c=context(),o=state.items[selected];$('selected-name').textContent=NAMES[selected]||'Nothing selected';$('action').textContent=c.label;$('action').disabled=state.phase!=='working'||c.disabled;const markup=c.buttons.map(([id,label])=>`<button class="secondary" data-command="${id}">${label}</button>`).join('');if(markup!==controlsMarkup){$('fine-controls').innerHTML=markup;controlsMarkup=markup;}$('action-note').textContent=note||c.hint;$('instrument').innerHTML=o&&'water'in o?`<p>${o.water.toFixed(1)} mL${o.id==='flask'?` · ${(o.chips+o.powder).toFixed(3)} g carbonate remaining`:''}</p>`:o?.kind==='spatula'?`<p>Loaded: ${(o.chips+o.powder).toFixed(2)} g</p>`:'';
 $('clock').textContent=state.clock?'Stop clock':'Start / resume clock';$('clock-reading').textContent=`${state.elapsed.toFixed(1)} s · ${state.collected.toFixed(1)} mL`;$('connection-status').textContent=connected(state)?state.tight?'Gas line connected · tight seal':'Gas line connected · leaking':'Gas line open · produced CO₂ escapes';for(const id of ['clock','record','save-trial','next-trial','logger','finish'])$(id).disabled=state.phase!=='working';for(const el of $('equipment').children)el.disabled=state.phase!=='working';menu?.sync();renderData();}
function select(id){if(state.phase!=='working')return;selected=id;note='';render();}
const coords=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(bench.getScreenCTM().inverse());
bench.addEventListener('pointerdown',e=>{const id=e.target.closest('[data-id]')?.dataset.id;if(!id||e.button!==0||state.phase!=='working')return;select(id);const p=coords(e),o=state.items[id];drag={id,start:p,dx:p.x-o.x,dy:p.y-o.y,active:false};bench.focus({preventScroll:true});bench.setPointerCapture(e.pointerId);e.preventDefault();});
bench.addEventListener('pointermove',e=>{if(!drag)return;const p=coords(e);if(!drag.active){if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)<4)return;detach(state,drag.id);drag.active=true;}physicsFor(state).moveHeld(drag.id,Math.max(65,Math.min(935,p.x-drag.dx)),Math.max(20,Math.min(510,p.y-drag.dy)));render();});
function release(e){if(!drag)return;const id=drag.id;if(drag.active&&menu?.wantsStore(e)&&menu.store(id))selected=null;else if(drag.active)placeItem(state);drag=null;render();}
bench.addEventListener('pointerup',release);bench.addEventListener('pointercancel',release);
function action(command='normal'){if(state.phase!=='working')return;const o=state.items[selected];if(!active(o))return;note='';state.flow=[];
 if(o.kind==='spatula')note=scoop(state,command==='fine'?.01:.1)?'One solid portion handled.':'Place over a solid bottle or the open flask.';
 else if(o.kind==='vial'&&command!=='pour'){if(o.parent){o.parent=null;o.y-=75;physicsFor(state).sync();note='Vial removed; move it clear.';}else note=fitVial(state)?'Acid vial seated inside; its contents remain separate.':'Move the vial near the open flask.';}
 else if(o.kind==='bung'){if(o.parent){o.parent=null;o.y-=35;state.hose=false;physicsFor(state).sync();note='Bung removed.';}else note=fitBung(state)?'Bung fitted.':'Move the bung near the flask mouth.';}
 else if(o.kind==='gasSyringe'){if(command==='clamp'){if(state.links.length){state.links=[];physicsFor(state).sync();note='Clamp released.';}else note=clampSyringe(state)?'Syringe clamped.':'Move the syringe near the stand, with clear space.';}else if(command==='seal'){state.tight=!state.tight;note=state.tight?'Connector tightened.':'Connector loose; CO₂ can escape.';}else if(command==='zero'){zeroSyringe(state);note='Collected gas released.';}else note=connect(state)?state.hose?'Delivery tube connected.':'Delivery tube disconnected.':'Fit the bung and move the syringe within hose reach.';}
 else if(o.id==='flask'){if(mixVial(state)){if(command!=='mix-only'&&!state.clock&&state.elapsed===0&&!state.records.length)toggleClock(state);note='Inner vial tipped; reactants are now in contact.';}else note='Fit an acid-filled inner vial first, or pour acid directly onto the solid.';}
 else if(o.kind==='solidBottle')note=pour(state,o.id)>0?'One solid portion transferred.':'Hold above an open receiver. Use the spatula for finer portions.';
 else if('water'in o)note=pour(state,o.id,command==='fine'?1:10)>0?'One liquid portion transferred.':'Place above an open receiver. A fitted bung blocks filling.';
 if(state.flow.length)flowUntil=performance.now()+450;render();}
$('action').addEventListener('click',()=>action());$('fine-controls').addEventListener('click',e=>{const command=e.target.closest('[data-command]')?.dataset.command;if(command)action(command);});
document.addEventListener('keydown',e=>{if(e.code!=='Space'||state.phase!=='working')return;const c=e.target.closest?.('button,input,select,textarea');if(c&&c.id!=='action'&&!c.dataset.equipment)return;e.preventDefault();if(!e.repeat)action();});
$('equipment').addEventListener('click',e=>{const id=e.target.closest('[data-equipment]')?.dataset.equipment;if(id)select(id);});$('equipment').addEventListener('focusin',e=>{const id=e.target.closest('[data-equipment]')?.dataset.equipment;if(id&&id!==selected)select(id);});
$('clock').addEventListener('click',()=>{toggleClock(state);render();});$('record').addEventListener('click',()=>{record(state);render();});$('logger').addEventListener('change',e=>{state.logger=e.target.checked;state.nextLog=state.elapsed+2;});$('save-trial').addEventListener('click',()=>{saveTrial(state);note='Trial saved in this attempt.';dataMarkup='';render();});
$('next-trial').addEventListener('click',()=>{release();state=initializeStorage(nextTrial(state));selected=null;note='Fresh apparatus; saved trials remain below.';dataMarkup='';$('logger').checked=false;render();});
$('restart').addEventListener('click',()=>{state=initializeStorage(createState());selected=null;drag=null;note='';dataMarkup='';$('logger').checked=false;$('result').hidden=true;$('result').innerHTML='';render();});
$('finish').addEventListener('click',()=>{release();saveTrial(state);state.phase='finished';state.clock=false;render();const t=state.trials.at(-1),r=meanRate(t?.records||[]),charge=t?.charge,a=r?.a||{time:0,volume:0},b=r?.b||{time:10,volume:20},rate=(b.volume-a.volume)/(b.time-a.time),mass=charge?charge.chips+charge.powder:.2,acid=charge?.acid??.01,theory=Math.min(mass/CHEM.molarMass,acid/2)*CHEM.molarVolume;
 const questions=[{prompt:'Why does calcium carbonate powder usually react faster than the same mass of chips under matched conditions?',answers:['More exposed surface permits more frequent effective collisions.','More exposed surface makes each acid particle move much faster.','More exposed surface increases the total amount of carbonate.'],hint:'Separate reaction rate from reactant amount and particle energy.'},{prompt:`${r?'Use your recorded readings.':'Supplied example:'} At ${a.time.toFixed(1)} s the syringe reads ${a.volume.toFixed(1)} mL; at ${b.time.toFixed(1)} s it reads ${b.volume.toFixed(1)} mL. Calculate the mean collection rate over this interval.`,fields:[{id:'value',label:'Mean rate (mL s⁻¹)',answer:rate,tolerance:.02}],hint:'Mean rate = change in collected volume / elapsed time. An early interval estimates the early rate; it is not an exact tangent.'},{prompt:`${charge?(charge.changedAfterStart?'Use your cumulative charged amounts (later additions were made).':'Use your recorded starting charge.'):'Supplied example:'} ${mass.toFixed(3)} g CaCO₃ reacts with ${acid.toFixed(5)} mol HCl. CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂. Use M(CaCO₃) = 100.09 g mol⁻¹ and molar gas volume 24 000 mL mol⁻¹. Calculate the maximum CO₂ volume, accounting for the limiting reagent.`,fields:[{id:'value',label:'Maximum CO₂ (mL)',answer:theory,tolerance:.15}],hint:'Use min[m(CaCO₃)/M, n(HCl)/2] for CO₂ moles. Surface area changes rate, not this stoichiometric maximum.'}];
 const p=$('result');p.hidden=false;p.innerHTML=`<h2>Review your rate investigation</h2><p>CaCO₃(s) + 2HCl(aq) → CaCl₂(aq) + H₂O(l) + CO₂(g).</p><p>${state.trials.length>=2?'Compare your saved curves and control variables.':'Save at least two trials to compare chips and powder.'} A steeper early curve means a faster collection rate. Equal reactant amounts under matched conditions give the same theoretical final CO₂; leaks, an open flask, a late clock or an incomplete reaction can make measured curves differ.</p><p>Reaction and gas collection continue when the stopwatch is stopped. Readings are not replaced by ideal values. Model defaults: 20 °C, rounded molar gas volume 24.0 L mol⁻¹, 100 mL syringe capacity. Rate constants are uncalibrated teaching coefficients; gas dissolution, dead-volume filling, pressure and thermal effects are omitted.</p>${graph(state.trials,state)}${reviewQuestions('rates',questions)}`;bindReviewQuestions('rates',()=>{state.phase='complete';},questions);p.focus({preventScroll:true});p.scrollIntoView({behavior:'smooth',block:'start'});});
function frame(time){const dt=Math.min(.05,(time-last)/1000);last=time;if(state.phase==='working'){stepPhysics(state,dt,drag?.active?drag.id:null);stepChemistry(state,dt);render();}requestAnimationFrame(frame);}
menu=createEquipmentMenu({getState:()=>state,world:()=>physicsFor(state),groups,select,begin(id){select(id);detach(state,id);drag={id,dx:0,dy:0,active:true};},end:release,render,isDragging:()=>Boolean(drag?.active)});render();requestAnimationFrame(frame);
